import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaUserCircle, FaSignOutAlt, FaBook, FaCalendarAlt, FaBookOpen, FaUpload, FaGraduationCap } from 'react-icons/fa';
import { toast } from 'react-toastify';
import { useAuth } from '../../../context/AuthContext';
import courseService from '../../../services/courseService';
import enrollmentService from '../../../services/enrollmentService';
import videoService from '../../../services/videoService';
import Spinner from '../../../components/Spinner';

import '../../../App.css';
import '../../../styles/TeacherDashboard.css';

const TeacherDashboard = () => {
  const navigate = useNavigate();
  const { user, logout } = useAuth();

  const [loading, setLoading] = useState(true);
  const [courses, setCourses] = useState([]);

  // Wireframe UI States
  const [activeTab, setActiveTab] = useState('courses');
  const [selectedCourse, setSelectedCourse] = useState(null);

  // Mock Data for the wireframe
  const mockYears = ['First Year (FY)', 'Second Year (SY)', 'Third Year (TY)'];
  const mockSubjects = {
    'First Year (FY)': ['Mathematics', 'Communication Skills', 'C Programming'],
    'Second Year (SY)': ['Python', 'Data Structures', 'DBMS'],
    'Third Year (TY)': ['AI', 'Machine Learning', 'Cloud Computing']
  };

  // Fetch teacher data on mount
  useEffect(() => {
    const fetchTeacherData = async () => {
      try {
        setLoading(true);
        // Fetch teacher's courses
        const coursesData = await courseService.getAllCourses();
        const teacherCourses = (coursesData || []).filter(course => {
          const isSelected = Array.isArray(user?.course) 
            ? user.course.includes(course.title) 
            : course.title === user?.course;
          return isSelected || course.teacher_id === user?.id || String(course._id) === String(user?.courseId);
        });

        if (teacherCourses.length > 0) {
           setCourses(teacherCourses);
        } else {
           // Fallback for Wireframe if no db courses exist
           setCourses([
             { _id: 'mock1', title: 'B.Sc. IT', description: 'Bachelor of Science in Information Technology' },
             { _id: 'mock2', title: 'B.Com', description: 'Bachelor of Commerce' }
           ]);
        }
      } catch (error) {
        console.error('Error fetching data:', error);
        // Fallback for Wireframe
        setCourses([
             { _id: 'mock1', title: 'B.Sc. IT', description: 'Bachelor of Science in Information Technology' },
             { _id: 'mock2', title: 'B.Com', description: 'Bachelor of Commerce' }
        ]);
      } finally {
        setLoading(false);
      }
    };

    if (user) {
      fetchTeacherData();
    }
  }, [user]);

  const handleLogout = async () => {
    await logout();
    navigate('/login');
  };

  // HEADER (Navbar)
  const renderHeader = () => (
    <nav className="wireframe-header">
      <div className="header-logo">
        <FaGraduationCap size={30} /> 
        <span>E-Learn Platform</span>
      </div>
      <div className="header-links">
        <span className={activeTab === 'courses' ? 'active' : ''} onClick={() => { setActiveTab('courses'); setSelectedCourse(null); }}>Courses</span>
        <span className={activeTab === 'upload-content' ? 'active' : ''} onClick={() => { setActiveTab('upload-content'); setSelectedCourse(null); }}>Upload Content</span>
        <span className={activeTab === 'my-courses' ? 'active' : ''} onClick={() => setActiveTab('my-courses')}>Manage</span>
      </div>
      <div className="header-profile">
        <FaUserCircle size={26} /> 
        <span>{user?.name || 'Profile'}</span>
        <FaSignOutAlt size={22} className="logout-icon" onClick={handleLogout} title="Logout" />
      </div>
    </nav>
  );

  // SIDEBAR (Admin/Teacher Tools)
  const renderSidebar = () => (
    <aside className="wireframe-sidebar">
      <h3>Admin/Teacher Tools</h3>
      <ul>
        <li className={activeTab === 'courses' || activeTab === 'my-courses' ? 'active' : ''} onClick={() => { setActiveTab('courses'); setSelectedCourse(null); }}>
          <FaBook /> My Courses
        </li>

        <li className={activeTab === 'manage-subjects' ? 'active' : ''} onClick={() => setActiveTab('manage-subjects')}>
          <FaBookOpen /> Manage Subjects
        </li>
        <li className={activeTab === 'upload-content' ? 'active' : ''} onClick={() => { setActiveTab('upload-content'); setSelectedCourse(null); }}>
          <FaUpload /> Upload Content
        </li>
      </ul>
    </aside>
  );

  // MAIN SECTION (Course List Grid)
  const renderCourseList = () => (
    <div className="wireframe-section slide-in">
      <h2>Course List</h2>
      <div className="course-grid">
        {courses.map(course => (
          <div key={course._id} className="wf-course-card">
            <div className="wf-course-icon"><FaBook size={40} /></div>
            <h3>{course.title}</h3>
            <p>{course.description || 'Administer course details, years, and subjects.'}</p>
            <button className="wf-btn" onClick={() => { 
                setSelectedCourse(course); 
                setActiveTab('course-detail'); 
            }}>
              View Details
            </button>
          </div>
        ))}
      </div>
    </div>
  );

  // COURSE DETAIL PAGE
  const renderCourseDetail = () => {
    if (!selectedCourse) return null;
    return (
      <div className="wireframe-section slide-in">
        <div className="wf-breadcrumb">
          <button className="wf-btn-outline" onClick={() => { setActiveTab('courses'); setSelectedCourse(null); }}>&larr; Back to Courses</button>
        </div>
        <div className="course-header-banner">
            <h2>{selectedCourse.title}</h2>
            <p className="wf-subtitle">Manage curriculum and content for this course.</p>
        </div>

        <div className="year-list">
          {mockYears.map((year, idx) => (
            <div key={idx} className="year-block">
              <div className="year-header">
                <FaCalendarAlt color="#10b981" />
                <h3>{year}</h3>
              </div>
              <div className="subject-list">
                {mockSubjects[year]?.map((subject, sIdx) => (
                  <div key={sIdx} className="subject-card">
                    <h4>{subject}</h4>
                    <p className="wf-small-text">Syllabus modules and materials</p>
                    <button className="wf-btn wf-btn-small" onClick={() => {
                        setSelectedCourse(selectedCourse);
                        setActiveTab('upload-content');
                    }}>Manage Content</button>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  // UPLOAD CONTENT PAGE
  const renderUploadContent = () => (
    <div className="wireframe-section slide-in center-form">
      <h2>Upload Content</h2>
      <p className="wf-subtitle">Add new learning materials to the curriculum.</p>

      <form className="wf-upload-form" onSubmit={(e) => { 
          e.preventDefault(); 
          toast.success('Successfully saved and stored in Mongo GridFS Bucket!'); 
          e.target.reset();
      }}>
        <div className="form-group">
          <label>Select Course</label>
          <select required defaultValue={selectedCourse?._id || ''}>
            <option value="" disabled>-- Choose Course --</option>
            {courses.map(c => <option key={c._id} value={c._id}>{c.title}</option>)}
          </select>
        </div>

        <div className="form-row">
            <div className="form-group half-width">
              <label>Select Year</label>
              <select required>
                <option value="" disabled>-- Choose Year --</option>
                {mockYears.map(y => <option key={y} value={y}>{y}</option>)}
              </select>
            </div>

            <div className="form-group half-width">
              <label>Select Subject</label>
              <select required>
                <option value="" disabled>-- Choose Subject --</option>
                <option value="python">Python</option>
                <option value="java">Java Programming</option>
                <option value="math">Mathematics</option>
                <option value="dbms">DBMS</option>
              </select>
            </div>
        </div>

        <div className="form-group file-upload-group">
          <label>Upload Material (PDF / Video / Quiz)</label>
          <div className="file-drop-zone">
             <FaUpload size={30} color="#9ca3af" />
             <p>Drag and drop files here, or click to browse</p>
             <input type="file" required className="file-input-hidden" />
          </div>
        </div>

        <button type="submit" className="wf-btn-large">
           <FaUpload style={{marginRight: '8px'}} /> Save to GridFS
        </button>
        <div className="wf-note-box">
           <p><strong>Note:</strong> Files are securely uploaded and stored in the <code>mongo grid fs bucket</code> for scalable access.</p>
        </div>
      </form>
    </div>
  );

  // RENDER SWITCH
  const renderContent = () => {
    switch(activeTab) {
      case 'courses': return renderCourseList();
      case 'course-detail': return renderCourseDetail();
      case 'upload-content': return renderUploadContent();

      case 'manage-subjects': return <div className="wireframe-section"><h2>Manage Subjects</h2><p>Curriculum design and subject management go here.</p></div>;
      case 'my-courses': return renderCourseList();
      default: return renderCourseList();
    }
  };

  if (loading) return <Spinner message="Loading Teacher Dashboard..." />;

  return (
    <div className="wireframe-layout">
      {renderHeader()}
      <div className="wireframe-body">
        {renderSidebar()}
        <main className="wireframe-main">
          {renderContent()}
        </main>
      </div>
    </div>
  );
};

export default TeacherDashboard;
